"""FIFO record framing, user faults and all DMA prepare/finish paths."""
def register(topic, q, detail):
    def lesson(title, path, symbol, why, principle, use, reading, qa, cards):
        topic(title, '라이브러리·알고리즘', path, symbol,
              why, principle, use, reading, *(q(*x) for x in qa),
              details=[detail(*x) for x in cards])

    lesson('FIFO 레코드 길이·1·2바이트 헤더와 표현 한계', 'lib/kfifo.c', '__kfifo_peek_n',
        '바이트 스트림에서 개별 메시지의 경계를 길이 헤더로 표시하는 방법을 배웁니다.',
        'recsize 1은 길이를 한 바이트에, 2는 낮은 바이트와 높은 바이트 순서로 저장합니다. __KFIFO_POKE와 PEEK는 각 바이트의 누적 위치를 mask로 감아 헤더 자체가 배열 끝을 넘어도 처리합니다. __kfifo_max_r는 (1<<(recsize*8))-1로 최대 길이를 제한해 1바이트 255, 2바이트 65535를 제공합니다.',
        '지원하는 recsize 1 또는 2와 바이트 원소형을 사용합니다. len_r와 공개 peek_len의 record 경로는 빈 큐를 먼저 검사하지 않으므로 실제 다음 레코드가 있을 때 읽습니다. 일반 큐의 peek_len은 사용 원소 수에 원소 바이트 크기를 곱한 값입니다.',
        'peek_n의 --recsize와 poke_n의 높은 바이트 이동을 읽으세요.',
        [('길이 0x1234를 2바이트 레코드 헤더로 저장하는 순서는?', '낮은 0x34 뒤 높은 0x12다', '항상 높은 0x12 뒤 낮은 0x34다', '첫 위치에는 unsigned char 길이를, 다음 위치에는 n>>8을 저장합니다. 수치 헤더의 바이트 순서를 원본으로 확인해야 합니다.'),
         ('1바이트 길이 헤더로 표현 가능한 최대 payload는?', '255바이트다', '256바이트다', '길이 필드의 최댓값은 2^8-1입니다. 전체 저장 여유에서는 이 payload 외에 헤더 한 바이트도 필요합니다.')],
        [('단순화 전제', 'peek_n은 1 또는 2바이트 헤더만 처리합니다. 임의 recsize를 넣으면 더 많은 바이트를 일반적으로 해석하는 함수가 아닙니다.'),
         ('길이 0', '길이 0 레코드도 헤더 공간을 사용합니다. payload 반환 0만으로 빈 큐와 같은 상태라고 판단하지 말고 실제 카운터와 empty 조건을 확인합니다.')])

    lesson('FIFO 레코드 입력·헤더까지 들어갈 때만 전체 공개', 'lib/kfifo.c', '__kfifo_in_r',
        '일반 부분 입력과 달리 메시지 전체를 하나의 레코드로 공개하는 동작을 배웁니다.',
        'len+recsize가 여유보다 크면 0을 반환하고 카운터를 바꾸지 않습니다. 충분하면 길이 헤더를 쓴 뒤 payload를 in+recsize 위치에 복사하고 in을 len+recsize만큼 늘립니다. 반환은 payload 바이트 길이입니다. 일반 입력처럼 공간만큼 메시지 일부를 별도 레코드로 잘라 넣지 않습니다.',
        '메모리 입력 경로는 caller가 길이 헤더의 표현 한계를 지켜야 합니다. __kfifo_in_r 자체는 max_r로 len을 줄이지 않습니다. 길이 0도 헤더를 공개할 수 있으므로 반환 0과 실패 여부는 카운터·상태 계약으로 구분해야 합니다.',
        '여유 검사, poke_n, payload 시작과 in 갱신을 읽으세요.',
        [('여유 5바이트, 헤더 2바이트, payload 4바이트이면?', '아무 레코드도 공개하지 않고 0을 반환한다', 'payload 3바이트를 부분 레코드로 자동 공개한다', '필요 공간은 6바이트로 여유를 넘습니다. 레코드 입력은 전체 헤더와 payload가 들어갈 때만 수행합니다.'),
         ('메모리 레코드 입력이 모든 len을 자동으로 255로 줄이는가?', '아니며 지원 폭의 길이 조건을 caller가 지켜야 한다', 'recsize 1이면 항상 내부에서 자동 축소한다', '__kfifo_in_r는 여유만 검사하고 max_r를 호출하지 않습니다. 사용자 복사·DMA 일부 경로의 길이 제한을 모든 API에 확대하지 않습니다.')],
        [('저장과 공개', 'payload 복사 helper의 배리어 뒤 in을 갱신합니다. 헤더를 쓴 시점과 독자가 볼 수 있는 누적 카운터 공개를 구분합니다.'),
         ('공개 매크로', 'kfifo_in은 recsize에 따라 일반 __kfifo_in 또는 이 record 경로를 선택합니다. 동일 이름이어도 부분 처리 계약이 달라집니다.')])

    lesson('FIFO 레코드 출력·짧게 복사해도 전체 메시지 소비', 'lib/kfifo.c', '__kfifo_out_r',
        '출력 버퍼가 메시지보다 작을 때 반환 길이와 소비 길이가 달라지는 이유를 배웁니다.',
        'out_copy_r는 헤더에서 실제 길이 n을 읽고 요청 len을 min(len,n)으로 제한해 payload를 복사합니다. out_r는 실제 복사 길이를 반환하지만 out을 n+recsize만큼 늘려 전체 레코드를 소비합니다. out_peek_r는 같은 복사 후 out을 유지합니다. skip_r는 복사 없이 헤더 길이와 헤더 공간 전체를 건너뜁니다.',
        '메시지를 온전히 받고 싶으면 peek_len으로 길이를 확인하고 충분한 버퍼를 제공합니다. 짧은 out 뒤 나머지를 이어 읽을 수 있다고 가정하지 않습니다. 빈 out·peek은 0을 반환하지만 skip_r 자체에는 빈 검사 없이 헤더를 읽는 조건이 있습니다.',
        '반환 len과 카운터에 더하는 n+recsize를 비교하세요.',
        [('길이 10 레코드를 버퍼 4로 out하면?', '4바이트를 반환하고 레코드 전체를 소비한다', '4바이트만 소비해 나머지 6이 같은 메시지로 남는다', '복사는 요청 크기로 제한하지만 out은 헤더에 저장된 전체 길이를 더합니다. 짧은 출력은 나머지 payload를 버립니다.'),
         ('같은 길이 10 레코드를 버퍼 4로 out_peek하면?', '4바이트를 복사하고 전체 레코드는 남긴다', '항상 전체 레코드를 소비한다', 'peek은 카운터를 갱신하지 않습니다. 필요한 버퍼 크기를 확인하거나 앞부분을 관찰할 때 소비와 구분합니다.')],
        [('0 요청', '유효한 레코드에 out 길이 0을 주어도 전체 레코드가 소비될 수 있습니다. 반환 payload 길이와 상태 변화를 함께 이해해야 합니다.'),
         ('동적 레코드형', 'kfifo_rec_ptr_1·2도 같은 recsize 분기로 연결됩니다. 외부 저장 형태의 준비와 소유권은 일반 PTR 객체의 규약을 따릅니다.')])

    lesson('FIFO 레코드 선형 조회·v6.12의 실제 경계 차이', 'lib/kfifo.c', '__kfifo_out_linear_r',
        '비슷한 함수 이름이어도 실제 구현의 반환·경계 조건을 확인해야 하는 이유를 배웁니다.',
        '일반 선형 조회는 out을 mask로 감고 배열 끝까지 길이를 제한합니다. 이 record 함수는 빈 큐면 즉시 0이고, 있으면 tail=out+recsize를 그대로 저장하고 min(요청,레코드 길이)만 반환합니다. tail을 mask로 감지 않고 배열 끝 제한도 하지 않습니다. 따라서 헤더의 일반적인 선형 구간 설명을 record 경로의 안전 보장으로 사용할 수 없습니다.',
        'record payload가 감겨 있거나 누적 out이 버퍼 범위를 넘은 경우 반환 tail·길이로 memcpy하지 않습니다. 안전한 record 복사가 필요하면 out_peek·out의 두 조각 복사 경로를 사용합니다. 빈 record의 linear_ptr도 tail이 기록되지 않는 내부 분기를 확인해야 합니다.',
        '일반 min3와 record min, tail의 마스크 유무를 대조하세요.',
        [('용량 16, record out=14, 헤더 1, payload 4의 실제 record linear 반환은?', 'tail 15와 길이 4지만 연속 접근은 1바이트만 가능하다', '항상 안전한 연속 길이 1만 반환한다', '원본 record 함수는 배열 끝까지 남은 길이를 제한하지 않습니다. payload는 위치 15 뒤 배열 처음으로 감기므로 반환 4를 연속 memcpy에 쓰면 범위를 넘습니다.'),
         ('빈 record 큐에서 이 함수가 tail을 기록하는가?', '아니며 빈 반환이 tail 대입보다 앞에 있다', '항상 out&mask를 tail에 기록한다', 'in==out이면 즉시 0입니다. 일반 선형 조회와 달리 빈 경우 tail이 초기화되지 않으므로 뒤 pointer wrapper의 계산까지 무조건 안전하다고 단정하지 않습니다.')],
        [('원본 보존', '교재는 고정된 v6.12 구현의 동작을 설명합니다. 배열 끝 제한을 임의로 추가한 코드로 원본이 안전했다고 보여 주지 않습니다.'),
         ('반환 관찰 시험', 'fixture는 record tail과 반환 길이의 실제 값을 비교하지만 안전하지 않은 연속 범위를 읽지 않습니다. 관찰된 숫자가 올바른 선형 메모리 범위라는 주장이 아닙니다.')])

    lesson('FIFO 사용자 복사·바이트 오류를 완전한 원소로 환산', 'lib/kfifo.c', 'kfifo_copy_from_user',
        '사용자 메모리 복사가 중간에 실패할 때 실제 공개 가능한 원소 수를 계산하는 방법을 배웁니다.',
        '일반 from_user·to_user는 요청 바이트를 esize로 나누어 완전한 원소만 처리합니다. 두 조각 중 첫 복사가 실패하면 실패 바이트와 아직 시도하지 않은 두 번째 조각을 합칩니다. 실패 수를 DIV_ROUND_UP으로 원소 수로 올려 부분 원소를 제외합니다. copied는 완전한 원소의 바이트 수이고 카운터는 그 원소 수만 늘립니다. 실패가 있으면 -EFAULT입니다.',
        'err와 copied를 함께 확인하여 부분 성공을 처리합니다. 실패 부분의 메모리가 전혀 바뀌지 않는다는 계약은 아닙니다. 내부 __kfifo_*의 int 반환과 공개 매크로의 must_check helper 형식까지 읽어 오류 결과를 올바른 변수·비교에 연결합니다.',
        '첫 조각 ret+len-l, 원소 올림과 copied=len-ret*esize를 읽으세요.',
        [('4바이트 원소에서 10바이트 요청이 정상 복사되면?', '2개 원소·8바이트가 처리된다', '항상 10바이트를 2.5개 원소로 공개한다', '공개 요청은 바이트지만 내부는 완전한 원소 단위입니다. len/esize가 2이므로 나머지 2바이트는 처리 길이에 들어가지 않습니다.'),
         ('한 원소의 일부 바이트만 복사되면 그 원소를 카운터에 포함하는가?', '아니며 실패 원소 수를 올림하여 제외한다', '조금이라도 복사되면 항상 전체 원소로 공개한다', '실패 바이트를 원소 수로 올리는 계산은 불완전 원소를 제외합니다. 물리적으로 바뀐 바이트와 공개된 완전한 원소를 구분해야 합니다.')],
        [('출력 오류', 'kfifo_copy_to_user도 같은 두 조각·올림 규칙을 사용합니다. 사용자 목적지에 일부 바이트가 써져 있어도 out은 완전한 원소까지만 진행할 수 있습니다.'),
         ('단위와 형식', 'copied는 바이트, 일반 in·out의 카운터는 원소입니다. kfifo_from_user의 uint must-check 연결과 to_user의 int helper 차이는 원본 형식이며 내부 int 오류를 단순 처리 개수로 해석하지 않습니다.')])

    lesson('FIFO 레코드 사용자 복사·오류 시 카운터 유지', 'lib/kfifo.c', '__kfifo_from_user_r',
        '레코드 사용자 복사에서 일부 물리 복사와 전체 메시지 공개의 차이를 배웁니다.',
        'from_user_r는 max_r로 요청을 길이 폭에 제한하고 헤더 포함 여유가 부족하면 copied=0으로 정상 반환합니다. 여유가 있으면 헤더와 payload를 쓰지만 복사 실패 시 copied=0,-EFAULT이고 in은 유지됩니다. to_user_r도 실패면 copied=0이고 out을 유지합니다. 출력 성공은 실제 복사가 짧아도 전체 n+recsize를 소비합니다.',
        'copied=0이 공간 부족인지 오류인지 err로 구분합니다. 실패 때 큐 카운터가 유지되어도 버퍼나 사용자 목적지가 일부 바뀔 수 있습니다. 재시도·외부 부작용을 처리할 때 전혀 쓰지 않았다고 가정하지 않습니다.',
        'max_r, copied=0, 오류 반환과 성공 카운터 대입 위치를 읽으세요.',
        [('record 사용자 입력 복사 중 실패하면 in은?', '이전 값으로 유지되고 copied=0,-EFAULT다', '부분 payload만큼 무조건 증가한다', '이 경로는 전체 레코드 공개를 위해 복사 성공 후에만 in을 갱신합니다. 일반 원소 사용자 복사의 부분 처리와 다른 계약입니다.'),
         ('길이 8 record를 사용자 버퍼 3으로 정상 출력하면?', '3바이트를 보고하고 전체 record를 소비한다', '3바이트만 소비하고 같은 record 나머지를 남긴다', '성공 출력의 out 갱신은 n+recsize입니다. 반환 copied가 실제 복사 길이여도 전체 record가 사라집니다.')],
        [('빈 출력', 'record to_user는 빈 큐면 copied=0,err=0입니다. 오류 없음이 자료를 읽었다는 뜻은 아니므로 copied와 empty 상태를 함께 해석합니다.'),
         ('모의 uaccess', '실행 fixture는 지정 복사 호출의 잃은 바이트를 모의합니다. 실제 사용자 주소의 권한 검사·페이지 폴트·kernel copy 구현을 실행한 것으로 표시하지 않습니다.')])

    lesson('FIFO scatterlist·감긴 두 조각과 DMA 주소', 'lib/kfifo.c', 'setup_sgl',
        '원형 버퍼의 비연속 구간을 장치 전송용 설명 항목으로 구성하는 방법을 배웁니다.',
        'setup_sgl은 원소 위치·길이를 바이트로 바꾸고 배열 끝까지 첫 조각과 배열 처음의 두 번째 조각을 나눕니다. setup_sgl_buf는 항목 여유나 길이가 없으면 0, 있으면 sg_set_buf로 항목 한 개를 설정합니다. dma가 DMA_MAPPING_ERROR가 아니면 dma+data_offset 주소와 바이트 길이를 별도로 저장합니다. 반환은 만들어진 항목 개수입니다.',
        '실제 scatterlist 배열의 nents와 저장 공간을 제공하고 이미 매핑된 DMA 주소와 CPU 버퍼 주소를 구분합니다. 이 helper는 실제 dma_map 호출이나 장치 시작을 수행하지 않습니다. 한 항목만 제공하면 감긴 나머지를 모두 표현하지 못할 수 있습니다.',
        '두 setup_sgl_buf 호출의 nents-n과 data_offset을 읽으세요.',
        [('감긴 자료에 nents=1이면 항상 전체 요청을 표현하는가?', '아니며 첫 조각만 설명될 수 있다', '항상 두 항목을 배열 밖에 자동 추가한다', '두 번째 호출은 남은 항목 수를 확인합니다. 여유가 없으면 0을 반환하므로 반환 항목 수와 실제 설명 길이를 확인해야 합니다.'),
         ('매핑 주소 dma와 CPU data 포인터의 의미는?', '서로 다른 주소 공간의 표현이며 용도를 구분한다', '모든 장치에서 반드시 같은 숫자다', '원본은 CPU 버퍼로 sg_set_buf를 수행하고 제공된 dma 주소를 별도 필드에 넣습니다. 두 주소가 동일하다고 가정하지 않습니다.')],
        [('DMA sentinel', 'DMA_MAPPING_ERROR를 넘긴 경로는 미리 매핑된 주소 필드를 설정하지 않습니다. 뒤의 실제 매핑·동기화·장치 처리는 사용하는 코드의 책임입니다.'),
         ('영 길이', '길이 0이면 항목을 만들지 않습니다. nents는 유효한 비음수 배열 용량이어야 하며 임의의 음수 값이 안전한 오류로 검증되는 함수가 아닙니다.')])

    lesson('FIFO DMA 일반 경로·준비와 완료의 단위', 'lib/kfifo.c', '__kfifo_dma_in_prepare',
        '장치 전송 범위를 준비하는 일과 완료한 자료를 카운터에 반영하는 일을 구분합니다.',
        '입력 prepare는 len을 여유 원소 수로, 출력 prepare는 사용 원소 수로 제한해 해당 in·out 위치의 scatterlist를 만듭니다. 카운터는 아직 바꾸지 않습니다. 공개 일반 in_finish는 완료 바이트를 원소 크기로 나눠 in에 더합니다. out_finish는 완료 바이트를 원소 수로 바꾸어 skip_count로 out을 늘립니다. finish는 별도 오류·용량 검사를 하지 않습니다.',
        'prepare의 요청 원소 수, 반환 항목 수와 finish의 실제 완료 바이트 수를 각각 확인합니다. 항목 부족·부분 장치 전송이면 실제 완료 범위만 finish에 제공합니다. prepare만으로 공간이 여러 writer에게 예약되거나 DMA 동기화가 완성되는 것은 아닙니다.',
        '두 prepare 제한과 header finish의 sizeof(type) 나눗셈을 읽으세요.',
        [('u32 큐의 DMA 완료 12바이트는 카운터를 얼마나 늘리는가?', '3개 원소만큼 늘린다', '12개 원소만큼 늘린다', '일반 finish는 바이트 len을 원소 크기 4로 나눕니다. prepare와 finish의 입력 단위를 구분해야 합니다.'),
         ('prepare가 반환한 2의 의미는?', 'scatterlist 항목 2개다', '무조건 전송 완료된 원소 2개다', 'prepare는 설명 항목을 구성하고 개수를 반환할 뿐입니다. 실제 장치 전송은 아직 수행하지 않았고 카운터도 갱신하지 않습니다.')],
        [('오류 검사 없음', '헤더는 finish에 오류 검사가 없다고 명시합니다. 준비된 범위보다 큰 완료 길이를 넘기면 사용량 조건을 깨뜨릴 수 있습니다.'),
         ('장치 동기화', '캐시·DMA 매핑 동기화와 장치 완료 확인은 이 함수가 대신 수행하지 않습니다. 자료가 CPU·장치에 유효하게 보이는 플랫폼 규약을 따릅니다.')])

    lesson('FIFO DMA 레코드·헤더 예약 위치와 전체 소비', 'lib/kfifo.c', '__kfifo_dma_in_finish_r',
        '레코드 DMA에서 payload와 길이 헤더를 서로 다른 시점에 처리하는 흐름을 배웁니다.',
        'record prepare는 nents가 0이면 BUG_ON이고 len을 max_r로 제한합니다. 입력은 len+recsize가 여유 안인지, 출력은 그 값이 사용량 안인지 검사하고 헤더 뒤 위치의 scatterlist를 구성합니다. 입력 finish는 완료 len을 길이 폭으로 제한하고 헤더를 쓴 뒤 in을 len+recsize 늘립니다. 출력 finish는 header의 skip_count record 분기로 다음 레코드 전체를 소비합니다.',
        '출력 prepare는 다음 헤더 길이를 직접 읽어 요청을 자동 제한하지 않으므로 실제 record 길이에 맞는 요청을 caller가 제공해야 합니다. 출력 완료 len이 짧아도 다음 record 전체가 건너뛰어집니다. 준비·완료의 실제 장치 범위와 헤더 공간을 함께 관리합니다.',
        'BUG_ON, len+recsize 검사, payload 시작과 공개 out_finish의 skip_count를 읽으세요.',
        [('record DMA 입력 4바이트, 헤더 2바이트의 성공 finish는?', '헤더를 쓰고 in을 총 6 늘린다', '헤더 없이 in을 4만 늘린다', 'payload 밖의 헤더 공간도 큐 저장을 사용합니다. finish는 길이를 헤더에 기록하고 len+recsize를 공개합니다.'),
         ('record DMA 출력 finish에 길이 2를 넘기면 항상 2바이트만 소비하는가?', '아니며 다음 레코드 전체를 소비한다', '언제나 레코드 앞 2바이트만 남김없이 소비한다', '공개 out_finish는 skip_count로 연결되고 record 분기는 count와 무관하게 한 레코드 전체를 건너뜁니다. 실제 요청·완료·메시지 소비 계약을 구분해야 합니다.')],
        [('출력 준비 범위', 'record out_prepare의 사용량 검사는 다음 레코드 경계 검사와 다릅니다. 사용량에 여러 record가 있더라도 하나의 payload 요청은 그 record 길이를 지켜야 합니다.'),
         ('모의 DMA 범위', 'fixture는 원본 descriptor 구성·주소 오프셋·카운터 finish를 실행합니다. 실제 DMA 엔진·IOMMU·캐시 일관성·장치 인터럽트의 실행 검증으로 확대하지 않습니다.')])
